function isRoastableBase(starch: string): boolean {
  return /potatoes|plantains|cannellini beans/.test(starch);
}

function prepareBase(starch: string): string {
  if (/potatoes/.test(starch)) {
    return `Boil ${starch} in salted water until easily pierced, 12 to 16 minutes, then drain well and keep warm.`;
  }
  if (/plantains/.test(starch)) {
    return `Roast ${starch} with a light coating of olive oil until browned and tender, 18 to 22 minutes.`;
  }
  if (/pitas/.test(starch)) return `Warm ${starch} until pliable, then wrap in a clean towel.`;
  if (/tortillas/.test(starch)) return `Bake ${starch} at 400°F until crisp, 7 to 10 minutes.`;
  if (/bread/.test(starch)) return `Toast ${starch} until crisp at the edges.`;
  if (/cooked and chilled brown rice/.test(starch)) return `Break up ${starch} so the grains are separate and ready for the skillet.`;
  if (/cans .* beans|cooked .* lentils/.test(starch)) return `Rinse ${starch} if needed, drain well, and warm gently.`;
  return `Cook ${starch} according to package directions. Keep warm, fluffing or separating it before serving.`;
}

function keepsFresh(ingredient: string, method: MealKitMethod): boolean {
  if (/cucumber|butter lettuce|mango|radishes|bean sprouts|cooked beets|baby kale/.test(ingredient)) return true;
  return (method === "bowl" || method === "sheet-pan") &&
    /shredded (?:red )?cabbage|carrots, (?:grated|shaved|cut into matchsticks)/.test(ingredient);
}

function prepareMain(primary: string): string {
  if (/ground /.test(primary)) return `Break ${primary} into rough pieces and season with half of 1 teaspoon kosher salt and black pepper.`;
  if (/tofu|chickpeas/.test(primary)) return `Pat ${primary} thoroughly dry, then season with half of 1 teaspoon kosher salt and black pepper.`;
  if (/mushrooms/.test(primary)) return `Brush any debris from ${primary}, then season with half of 1 teaspoon kosher salt and black pepper.`;
  return `Pat ${primary} dry, then season with half of 1 teaspoon kosher salt and black pepper.`;
}

function mainDoneness(primary: string): string {
  if (/chicken|ground turkey/.test(primary)) return "it reaches 165°F";
  if (/salmon|cod|tilapia|shrimp/.test(primary)) return "it reaches 145°F and is just opaque";
  if (/pork/.test(primary)) return "it reaches 145°F before resting";
  if (/ground beef/.test(primary)) return "it is deeply browned with no pink remaining";
  if (/steak/.test(primary)) return "it is browned outside and still tender";
  if (/tofu/.test(primary)) return "it is crisp and browned on at least two sides";
  if (/chickpeas/.test(primary)) return "the chickpeas are crisp and hot";
  if (/lentils/.test(primary)) return "the lentils are hot and beginning to crisp";
  if (/halloumi/.test(primary)) return "the halloumi is golden on both sides";
  if (/tortellini/.test(primary)) return "the tortellini are tender";
  if (/mushrooms/.test(primary)) return "the mushrooms are deeply browned";
  return "it is browned and hot throughout";
}

function instructionSet(spec: MealKitRecipeSpec): readonly string[] {
  const sauce = spec.sauce.join(", ");
  const cookedVegetables = spec.vegetables.filter((item) => !keepsFresh(item, spec.method));
  const freshVegetables = spec.vegetables.filter((item) => keepsFresh(item, spec.method));
  const vegetables = cookedVegetables.join(" and ");
  const fresh = freshVegetables.length ? ` Add ${freshVegetables.join(" and ")} fresh at serving.` : "";
  const base = prepareBase(spec.starch);
  const prep = prepareMain(spec.primary);
  const sauceStaysCold = /Greek yogurt|tahini|pesto/.test(sauce);

  if (spec.title === "Thai basil turkey lettuce cups") {
    return [
      `${base} Combine ${sauce} into a smooth sauce.`,
      `${prep} Heat 1 tablespoon olive oil in a large skillet over medium-high. Cook the turkey, breaking it into small crumbles, until ${mainDoneness(spec.primary)}; transfer to a plate.`,
      `Add the remaining 1 tablespoon olive oil and ${cookedVegetables.join(" and ")}. Cook until crisp-tender, 4 to 6 minutes. Return the turkey, remove from the heat, toss with the sauce and ${spec.finish}, and season with the remaining salt and pepper.`,
      `Set ${freshVegetables.join(" and ")} on the table with the warm rice. Spoon the basil turkey into the lettuce leaves and serve the rice alongside or tucked into each cup.`,
    ];
  }

  if (spec.title === "Cheddar turkey cottage pie skillet") {
    return [
      `Boil ${spec.starch} in salted water until tender, 12 to 16 minutes. Drain, mash with 1/2 cup of the listed broth, and keep warm.`,
      `${prep} Heat 1 tablespoon olive oil in an oven-safe skillet over medium-high. Cook the turkey, breaking it into crumbles, until ${mainDoneness(spec.primary)}.`,
      `Add the remaining oil, ${vegetables}, and the remaining sauce ingredients. Simmer until the carrots are tender and the filling is saucy, 7 to 9 minutes; season with the remaining salt and pepper.`,
      `Spread the mashed potatoes over the filling, top with ${spec.finish}, and broil until bubbling and spotted brown, 2 to 4 minutes. Rest 5 minutes before serving.`,
    ];
  }

  if (spec.method === "sheet-pan") {
    return [
      "Heat the oven to 425°F with a rack in the upper third. Coat a large rimmed sheet pan with 1 tablespoon olive oil.",
      `Combine ${sauce} into a smooth sauce. ${prep} Toss ${[...cookedVegetables, ...(isRoastableBase(spec.starch) ? [spec.starch] : [])].join(" and ")} with the remaining 1 tablespoon olive oil, the remaining salt, and pepper on the pan. Add the seasoned main ingredient without crowding.`,
      `Roast, turning the vegetables once, until ${spec.doneness}. Spoon a little sauce over the main ingredient after it leaves the oven; rest meat or fish for 3 minutes when applicable.`,
      `${isRoastableBase(spec.starch) ? "Keep the roasted base warm." : base} Divide the base among four plates, add the roasted main and vegetables, and spoon over the remaining sauce.${fresh} Finish ${spec.title} with ${spec.finish}.`,
    ];
  }
  if (spec.method === "noodle") {
    return [
      `Bring a large pot of water to a boil. Cook ${spec.starch} until just tender, reserve 1/2 cup cooking water, drain, and rinse only if the package directs.`,
      `Combine ${sauce} into a smooth sauce. ${prep} Heat 1 tablespoon olive oil in a large skillet over medium-high. Cook the main ingredient until ${mainDoneness(spec.primary)}; transfer to a plate.`,
      `Add the remaining 1 tablespoon olive oil and ${vegetables}. Cook until crisp-tender, 4 to 6 minutes. Remove from the heat, then add the sauce, noodles, main ingredient, and enough reserved water to make the sauce glossy; toss for 1 minute.`,
      `Taste and adjust with the remaining salt and pepper.${fresh} Divide ${spec.title} among four bowls and finish with ${spec.finish}.`,
    ];
  }
  if (spec.method === "stew") {
    return [
      `${base} Meanwhile, heat 1 tablespoon olive oil in a Dutch oven or deep skillet over medium-high.`,
      `Combine ${sauce} into a smooth sauce. ${prep} Cook the main ingredient until browned or aromatic, 4 to 6 minutes. Add ${vegetables} and the remaining 1 tablespoon olive oil; cook 3 minutes.`,
      `Stir in the sauce and 1 cup water unless broth is already listed. Simmer gently, partially covered, until ${spec.doneness}, stirring occasionally and thinning with water if needed.`,
      `Season with the remaining salt and pepper. Spoon ${spec.title} over or alongside the prepared base.${fresh} Finish with ${spec.finish}.`,
    ];
  }
  if (spec.method === "bowl") {
    return [
      `${base} Combine ${sauce} into a smooth dressing or glaze.`,
      `${prep} Heat 1 tablespoon olive oil in a large skillet over medium-high and cook the main ingredient until ${mainDoneness(spec.primary)}; transfer to a plate.`,
      `Add the remaining 1 tablespoon olive oil and ${vegetables}. Cook until browned or crisp-tender, 4 to 6 minutes, then season with the remaining salt and pepper.`,
      `Build four bowls with the prepared base, cooked vegetables, and main ingredient.${fresh} Spoon over the sauce and finish ${spec.title} with ${spec.finish}.`,
    ];
  }
  return [
    `${base} Combine ${sauce} into a smooth sauce.`,
    `${prep} Heat 1 tablespoon olive oil in a large skillet over medium-high. Cook the main ingredient until ${mainDoneness(spec.primary)}; transfer to a plate.`,
    `Add the remaining 1 tablespoon olive oil and ${vegetables}. Cook until crisp-tender, 4 to 6 minutes. Return the main ingredient, ${sauceStaysCold ? "remove the skillet from the heat, add" : "add"} the sauce, and ${sauceStaysCold ? "toss until evenly coated" : "simmer 1 to 2 minutes until glossy"}.`,
    `Season with the remaining salt and pepper. Divide the prepared base among four plates, add ${spec.title}.${fresh} Finish with ${spec.finish}.`,
  ];
}

